code.java:
class Solution {
    public int change(int amount,int[] coins){
        int[] ways=new int[amount+1];
        ways[0]=1;
        for(int coin:coins)for(int sum=coin;sum<=amount;sum++)ways[sum]+=ways[sum-coin];
        return ways[amount];
    }
}

code.kotlin:
class Solution {
    fun change(amount:Int,coins:IntArray):Int{
        val ways=IntArray(amount+1);
        ways[0]=1;
        for(coin in coins)for(sum in coin..amount)ways[sum]+=ways[sum-coin];
        return ways[amount]
    }
}

code.cpp:
class Solution {
    public: int change(int amount,vector<int>& coins){
        vector<int> ways(amount+1);
        ways[0]=1;
        for(int coin:coins)for(int sum=coin;sum<=amount;++sum)ways[sum]+=ways[sum-coin];
        return ways[amount];
    }
};
